import sympy
from sympy.abc import x, y, z, w
from sympy import QQ, ZZ, GF

def conditions(witness) -> list[bool]:
    try:
        F = witness['F']
        V = witness['vars']
        J = witness['J']
        x_val = witness['x']
        y_val = witness['y']
        z_val = witness['z']
        a = witness['a']
        b = witness['b']
    except (TypeError, KeyError):
        return [False, False, False]
        
    # H1: F is a field
    try:
        h1 = F.is_Field
    except Exception:
        h1 = False
        
    # H2: I is the principal ideal generated by xy - z^2 in R
    # By our witness construction, R = F[V]/J and I is generated by x_val*y_val - z_val**2.
    # We simply verify the structural integrity of the ring presentation.
    try:
        h2 = isinstance(J, list) and isinstance(V, list) and all(isinstance(v, sympy.Symbol) for v in V)
    except Exception:
        h2 = False
        
    # neg_Q: R/I is NOT an integral domain
    # This means either 1 in I (so R/I is the zero ring), or there exist a, b not in I such that a*b in I.
    try:
        w_expr = x_val * y_val - z_val**2
        K_gens = J + [w_expr]
        
        # Compute Groebner basis for the ideal K = J + (xy - z^2)
        G = sympy.groebner(K_gens, *V, domain=F)
        
        # Check if 1 is in the ideal (i.e., R/I is the zero ring)
        rem_1 = sympy.reduced(1, G, *V, domain=F)[1]
        if rem_1 == 0:
            neg_q = True
        else:
            # Check for zero divisors
            a_rem = sympy.reduced(a, G, *V, domain=F)[1]
            b_rem = sympy.reduced(b, G, *V, domain=F)[1]
            ab_rem = sympy.reduced(a*b, G, *V, domain=F)[1]
            
            neg_q = (a_rem != 0) and (b_rem != 0) and (ab_rem == 0)
    except Exception:
        neg_q = False
        
    return [bool(h1), bool(h2), bool(neg_q)]

CONDITION_LABELS = [
    "H_1: F is a field",
    "H_2: I is the principal ideal generated by xy - z^2 in R",
    "¬Q: R/I is not an integral domain"
]

